import type { Metadata } from 'next';
import { type Locale, localizedPath } from './locales';
import { ogAlt, ogSize } from '@/lib/og';

const OG_LOCALES: Record<Locale, string> = { en: 'en_US', es: 'es_US', pt: 'pt_BR' };

type PageCopy = { title: string; description: string };
type ShareImage = { url: string; alt: string };

/** The preview card generated by an opengraph-image file next to this page. */
export function ownShareImage(locale: Locale, path: string, alt: string): ShareImage {
  return { url: `${localizedPath(locale, path)}/opengraph-image`, alt };
}

/**
 * The link preview (WhatsApp, Facebook, iMessage). A page-level openGraph replaces the
 * layout's whole object, including its url and image, so every field is set here.
 * Without a url, Facebook treats the link as the home page and shows its preview instead.
 */
function shareMetadata(locale: Locale, path: string, { title, description }: PageCopy, image?: ShareImage) {
  return {
    type: 'website' as const,
    siteName: 'Jose Costa Realtor',
    title,
    description,
    url: localizedPath(locale, path),
    locale: OG_LOCALES[locale],
    images: [{ ...(image ?? { url: localizedPath(locale, '/opengraph-image'), alt: ogAlt(locale) }), ...ogSize }],
  };
}

/** Canonical URL and link preview for an English-only page. */
export function pageMetadata(path: string, copy: PageCopy, { image }: { image?: ShareImage } = {}): Metadata {
  return {
    ...copy,
    alternates: { canonical: path },
    openGraph: shareMetadata('en', path, copy, image),
  };
}

/** Canonical URL plus hreflang links for a page that exists in all three languages. */
export function translatedPageMetadata(
  locale: Locale,
  path: string,
  { title, description }: PageCopy,
  { absoluteTitle = false, image }: { absoluteTitle?: boolean; image?: ShareImage } = {}
): Metadata {
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: {
      canonical: localizedPath(locale, path),
      languages: {
        en: path,
        es: localizedPath('es', path),
        pt: localizedPath('pt', path),
        'x-default': path,
      },
    },
    openGraph: shareMetadata(locale, path, { title, description }, image),
  };
}
